// Post-build steps for @webmind/react:
//   1. copy the shared stylesheet to dist/webmind.css  (import "@webmind/react/styles.css")
//   2. assemble the dependency-free <script> widget from the SAME compiled core + stylesheet, so the
//      widget and the React components cannot drift apart.
// Output: ../../src/webmind/api/static/webmind-widget.js (committed; the Python package ships it).
import { copyFileSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const dist = join(root, "dist");
// WIDGET_OUT lets the test-suite assemble into a temp file to prove the committed bundle is current.
const out = process.env.WIDGET_OUT || join(root, "..", "..", "src", "webmind", "api", "static", "webmind-widget.js");

copyFileSync(join(root, "src", "webmind.css"), join(dist, "webmind.css"));

/** Turn a compiled ES module into plain script text: drop imports, drop `export`. */
function plain(file) {
  return readFileSync(join(dist, "core", file), "utf8")
    .replace(/^import .*$/gm, "")
    .replace(/^export \{\};?$/gm, "")
    .replace(/^export (async function|function|const|let|class)/gm, "$1")
    .replace(/^\/\/# sourceMappingURL=.*$/gm, "");
}

const css = readFileSync(join(root, "src", "webmind.css"), "utf8")
  .replace(/\/\*[\s\S]*?\*\//g, "")
  .replace(/\s+/g, " ")
  .replace(/\s*([{};,>])\s*/g, "$1")
  .replace(/;}/g, "}")
  .trim();

const header = `/*!
 * WebMind embeddable assistant: dependency-free, Apache-2.0.
 * GENERATED by sdk/react/scripts/postbuild.mjs from the shared core and stylesheet. Do not edit by hand.
 *
 * <script src="https://your-webmind-host/v1/widget.js"
 *         data-endpoint="https://your-webmind-host"
 *         data-token-url="/webmind-token"       optional: your backend returns {"token": "..."} for signed-in users
 *         data-title="Ask this site"            optional
 *         data-subtitle="..."                   optional: replaces the identity line ("Signed in as ..." / "Public visitor")
 *         data-login-url="/login"               optional: shows a "Sign in" link to anonymous visitors
 *         data-position="right"                 right | left
 *         data-theme="auto"                     auto | light | dark
 *         data-accent="#4353d6"                 optional accent color
 *         data-suggestions="Question one|Question two"   optional quick-start prompts (max 4)
 *         data-client-exports="aggregates"      aggregates (default) | all | off, downloads of results already shown
 *         data-streaming="true"                 false disables token streaming
 *         data-open="false"                     true opens the panel on load
 *         defer></script>
 *
 * Security: all server-provided text is rendered with DOM text nodes (never innerHTML); only http(s)
 * links are rendered; the widget never stores tokens; exports contain only what is already on screen,
 * and raw record exports go through the server's permission-checked export.
 */
`;

const parts = ["richtext.js", "chartgeom.js", "icons.js", "placement.js", "exports.js"].map(plain).join("\n");
const ui = readFileSync(join(root, "widget", "widget-ui.js"), "utf8");
const bundle = `${header}(function () {\n"use strict";\n${parts}\nconst WM_CSS = ${JSON.stringify(":host{all:initial}" + css)};\n${ui}\n})();\n`;
writeFileSync(out, bundle, "utf8");
console.log(`widget: ${out} (${(bundle.length / 1024).toFixed(1)} KB)`);
